DROP TABLE IF EXISTS journals CASCADE;

CREATE TABLE journals (
                          id BIGSERIAL PRIMARY KEY,
                          title VARCHAR(255),
                          description TEXT,
                          issue INTEGER NOT NULL,
                          year INTEGER NOT NULL,
                          contents TEXT,
                          cover VARCHAR(255),
                          pdf VARCHAR(255)
);

